\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"WordPress 7.0 リリーススケジュール更新版\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"https://ja.wordpress.org/2026/04/25/wordpress-7-0-release-party-updated-schedule/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 25 Apr 2026 01:20:57 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://ja.wordpress.org/?p=8091\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:176:\"以下は WordPress.org 公式開発ブログ (Make WordPress Core) の記事「WordPress 7.0 Release Party Updated Schedule」の翻訳です。誤字脱字・誤訳 [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"Akira Tachibana\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:14694:\"\n<p class=\"wp-block-paragraph\">以下は WordPress.org 公式開発ブログ (Make WordPress Core) の記事「<a href=\"https://make.wordpress.org/core/2026/04/22/wordpress-7-0-release-party-updated-schedule/\" target=\"_blank\" rel=\"noreferrer noopener\">WordPress 7.0 Release Party Updated Schedule</a>」の翻訳です。<br>誤字脱字・誤訳などがありましたら<a href=\"https://ja.wordpress.org/support/forum/alphabeta/\">フォーラムまでお知らせください</a>。</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">みなさんに朗報です ! WordPress 7.0の新しいリリース日は<strong>2026年5月20日</strong>になりました。</p>\n\n\n\n<p class=\"wp-block-paragraph\">ここ数週間でのみなさんの柔軟な対応に感謝します。世界中の WordPress コントリビューターが7.0リリースに必要なアーキテクチャ改善に向けて懸命に作業してきました。リリースチームの目標は、このバージョンが可能な限り<strong>安定</strong>し、<strong>高いパフォーマンス</strong>を発揮すること、そして WordPress 7.0で計画した重要な機能を提供することです。</p>\n\n\n\n<p class=\"wp-block-paragraph\">以下のテーブルは、各リリースパーティーの予定日時と、7.0マイルストーンにおける各パーティーのリリースリードをまとめた最新スケジュールです。ここには公開済みの過去のプレリリース版に加えて、ホスティング環境間の互換性確保を目的とした、(準備中の) ホスティング事業者向けのテスト協力の呼びかけも含まれています。</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>注意:</strong> 直近のプレリリース版は RC2でしたが、RC3は実質的にベータ版として扱われます。つまり、継続的なテストとフィードバック、特にホスティング事業者でのテストがこのリリースサイクルにおける、次フェーズの開発プロセスへの情報として非常に重要になります。引き続きテストへのご協力をお願いします !</p>\n\n\n\n<h2 class=\"wp-block-heading\">リリーススケジュール</h2>\n\n\n\n<p class=\"wp-block-paragraph\">通常と同じくこのスケジュールも直前で調整される可能性があります。また、ホスティング事業者からのフィードバックの影響によっては、適切に対応できるようタイムラインがさらに更新される場合もあります。リリースチームは、いかなる変更もできるだけ速やかに周知するよう努めます。<a href=\"https://wordpress.slack.com/archives/C02RQBWTW\">Slack の #core チャンネル</a>への投稿、変更に関する投稿の公開、そしてこの投稿の更新 (履歴も含む) を参照してください。</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><thead><tr><th class=\"has-text-align-left\" data-align=\"left\"><strong>日付</strong></th><th class=\"has-text-align-left\" data-align=\"left\"><strong>マイルストーン</strong></th><th class=\"has-text-align-left\" data-align=\"left\"><strong>司会 / リリースリード</strong></th><th class=\"has-text-align-left\" data-align=\"left\"><strong>コミッター</strong></th><th class=\"has-text-align-left\" data-align=\"left\"><strong>セキュリティ</strong></th><th class=\"has-text-align-left\" data-align=\"left\"><strong>ミッションコントロール (調整)</strong></th></tr></thead><tbody><tr><td class=\"has-text-align-left\" data-align=\"left\">