xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:67:\"返信先: Contact Form 7でのコンタクトフォームの定義\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:194:\"https://ja.wordpress.org/support/topic/contact-form-7%e3%81%a7%e3%81%ae%e3%82%b3%e3%83%b3%e3%82%bf%e3%82%af%e3%83%88%e3%83%95%e3%82%a9%e3%83%bc%e3%83%a0%e3%81%ae%e5%ae%9a%e7%be%a9/#post-11694057\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 28 Apr 2026 05:37:13 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:840:\"\n						\n						<p class=\"wp-block-paragraph\"><a href=\"https://ja.wordpress.org/support/users/yukinobu/\" rel=\"ugc\">Yukinobu Asakawa</a>様</p>\n\n\n\n<p class=\"wp-block-paragraph\">ご指摘、誠にありがとうございました。</p>\n\n\n\n<p class=\"wp-block-paragraph\">仰るとおり、外観→カストマイズ→追加CSSでCSSコードを追加しておりました。</p>\n\n\n\n<p class=\"wp-block-paragraph\">おかげさまで、全く同じお問い合わせフォームが一致しました。</p>\n\n\n\n<p class=\"wp-block-paragraph\">感謝致します。</p>\n\n\n\n<p class=\"wp-block-paragraph\"><blockquote class=\"imgur-embed-pub\" lang=\"en\" data-id=\"1e041zf\"><a href=\"https://imgur.com/1e041zf\" rel=\"nofollow ugc\">View post on imgur.com</a></blockquote><script async src=\"//s.imgur.com/min/embed.js\" charset=\"utf-8\"></script></p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"Zenzo Ono\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:194:\"https://ja.wordpress.org/support/topic/contact-form-7%e3%81%a7%e3%81%ae%e3%82%b3%e3%83%b3%e3%82%bf%e3%82%af%e3%83%88%e3%83%95%e3%82%a9%e3%83%bc%e3%83%a0%e3%81%ae%e5%ae%9a%e7%be%a9/#post-11694056\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:67:\"返信先: Contact Form 7でのコンタクトフォームの定義\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:194:\"https://ja.wordpress.org/support/topic/contact-form-7%e3%81%a7%e3%81%ae%e3%82%b3%e3%83%b3%e3%82%bf%e3%82%af%e3%83%88%e3%83%95%e3%82%a9%e3%83%bc%e3%83%a0%e3%81%ae%e5%ae%9a%e7%be%a9/#post-11694056\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 27 Apr 2026 17:40:16 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1516:\"\n						\n						<p class=\"wp-block-paragraph\">こんにちは。<br />サイトの移行に関してはいくつか問題点があると思いますが、移行はすでに実施済みのようですので、<br />お問い合わせフォームの表示の差異についてコメントします。</p>\n\n\n\n<p class=\"wp-block-paragraph\">「旧お問い合わせの表示」、「新お問い合わせの表示」を見比べると、見た目のカスタマイズをする、CSSのコードの ある or なし による違いかな？と感じます。<br />お問い合わせフォームの項目のコードをコピペしてくださったと記載いただいていますが、見た目を同じにするためには、CSS も同様にコピペをする必要があるはずです。<br />（ただ、新旧サイトで WordPress本体やテーマのバージョンなどの違いで完全に再現できない場合もあり、調整は必要かもしれません）</p>\n\n\n\n<p class=\"wp-block-paragraph\">CSS の記述する場所は、子テーマのCSSや追加CSS、プラグインを使う方法などいくつかあります。<br />以前にカスタマイズされた時にどこかに記述されたはずです。</p>\n\n\n\n<p class=\"wp-block-paragraph\">旧サイトのデータがある場合は、検証環境を今の公開されている環境とは別に構築して、どこにCSSが記述されているかを確認することで、CSSコードの移植もできると思います。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Yukinobu Asakawa\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:194:\"https://ja.wordpress.org/support/topic/contact-form-7%e3%81%a7%e3%81%ae%e3%82%b3%e3%83%b3%e3%82%bf%e3%82%af%e3%83%88%e3%83%95%e3%82%a9%e3%83%bc%e3%83%a0%e3%81%ae%e5%ae%9a%e7%be%a9/#post-11694054\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"Contact Form 7でのコンタクトフォームの定義\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:194:\"https://ja.wordpress.org/support/topic/contact-form-7%e3%81%a7%e3%81%ae%e3%82%b3%e3%83%b3%e3%82%bf%e3%82%af%e3%83%88%e3%83%95%e3%82%a9%e3%83%bc%e3%83%a0%e3%81%ae%e5%ae%9a%e7%be%a9/#post-11694054\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 27 Apr 2026 16:42:38 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:3770:\"\n						\n						<p class=\"wp-block-paragraph\">レンタルサーバーの引っ越しに伴うコンタクトフォームの表示の相違について伺います。</p>\n\n\n\n<p class=\"wp-block-paragraph\">レンタルサーバーのを某お名前.comさんから某Xserverさんへ引っ越しをして、Wordpressでのホームページを作成することにしました。</p>\n\n\n\n<p class=\"wp-block-paragraph\">しかし、某Xserverさんの用意しているWordpressの簡単移行のツールを使ってもエラーとなり、その他いろんな方法で引っ越しをしようと試みましたが、全ての方法でエラーが発生し、最終的にはドメイン名を変えて、一から手作業で作成しました。</p>\n\n\n\n<p class=\"wp-block-paragraph\">一つだけ、上手く行かない点が発生しております。Contact Form 7のプラグインでのお問い合わせのフォームの表示が違っているのです。</p>\n\n\n\n<p class=\"wp-block-paragraph\">随分昔に自分でお問い合わせフォームをいじった記憶があります。しかし、どの様にいじったかすっかり忘れてしまったので、お問い合わせのフォームを旧フォームから新フォームへコピー＆ペーストで行いました。</p>\n\n\n\n<p class=\"wp-block-paragraph\">しかしながら、表示に違いがあるのです。</p>\n\n\n\n<p class=\"wp-block-paragraph\">（旧お問い合わせの表示）</p>\n\n\n\n<p class=\"wp-block-paragraph\"><blockquote class=\"imgur-embed-pub\" lang=\"en\" data-id=\"a/11d7z82\"><a href=\"https://imgur.com/a/11d7z82\" rel=\"nofollow ugc\">View post on imgur.com</a></blockquote><script async src=\"//s.imgur.com/min/embed.js\" charset=\"utf-8\"></script></p>\n\n\n\n<p class=\"wp-block-paragraph\">（新お問い合わせの表示）</p>\n\n\n\n<p class=\"wp-block-paragraph\"><blockquote class=\"imgur-embed-pub\" lang=\"en\" data-id=\"AX1PfKV\"><a href=\"https://imgur.com/AX1PfKV\" rel=\"nofollow ugc\">View post on imgur.com</a></blockquote><script async src=\"//s.imgur.com/min/embed.js\" charset=\"utf-8\"></script></p>\n\n\n\n<p class=\"wp-block-paragraph\">（旧お問い合わせのフォームの編集内容）</p>\n\n\n\n<p class=\"wp-block-paragraph\"><blockquote class=\"imgur-embed-pub\" lang=\"en\" data-id=\"8I3Ucyy\"><a href=\"https://imgur.com/8I3Ucyy\" rel=\"nofollow ugc\">View post on imgur.com</a></blockquote><script async src=\"//s.imgur.com/min/embed.js\" charset=\"utf-8\"></script></p>\n\n\n\n<p class=\"wp-block-paragraph\">（新お問い合わせのフォームの編集内容）</p>\n\n\n\n<p class=\"wp-block-paragraph\"><blockquote class=\"imgur-embed-pub\" lang=\"en\" data-id=\"JEN8kLl\"><a href=\"https://imgur.com/JEN8kLl\" rel=\"nofollow ugc\">View post on imgur.com</a></blockquote><script async src=\"//s.imgur.com/min/embed.js\" charset=\"utf-8\"></script></p>\n\n\n\n<p class=\"wp-block-paragraph\">比較してみると、明らかに表示が違っています。</p>\n\n\n\n<p class=\"wp-block-paragraph\">何が原因かがわかりません。特に細かくいじった記憶もありません。</p>\n\n\n\n<p class=\"wp-block-paragraph\">もし、お分かりの方がいらっしゃいましたら、ご教示お願い致します。ご面倒お掛け致しますが、どうぞよろしくお願い致します。補足資料が必要な場合はお知らせくださいませ。</p>\n\n\n<ul id=\"bbp-topic-revision-log-11694054\" class=\"bbp-topic-revision-log\">\n\n	<li id=\"bbp-topic-revision-log-11694054-item-11694055\" class=\"bbp-topic-revision-log-item\">\n		このトピックは<a href=\"https://ja.wordpress.org/support/users/siliconvl001/\" title=\"Zenzo Ono のプロフィールを表示\" class=\"bbp-author-link\"><span  class=\"bbp-author-name\">Zenzo Ono</span></a>が2日、 13時間前に変更しました。\n	</li>\n\n</ul>\n\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"Zenzo Ono\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:153:\"https://ja.wordpress.org/support/topic/site-kit-by-google%e3%81%ae%e5%89%8a%e9%99%a4%e6%9c%89%e7%84%a1%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694053\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"返信先: Site Kit by Googleの削除有無について\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:153:\"https://ja.wordpress.org/support/topic/site-kit-by-google%e3%81%ae%e5%89%8a%e9%99%a4%e6%9c%89%e7%84%a1%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694053\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 27 Apr 2026 12:20:10 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:897:\"\n						\n						<p class=\"wp-block-paragraph\">水野さん、Google謹製のSite Kitは、ちゃんと、日本語版が存在はしているのです（完全でないにしろ）。そして新規にインストールすると、ちゃんと、日本語で表示されます。</p>\n\n\n\n<p class=\"wp-block-paragraph\">でも、プラグインは、アップデートが入りますよね。大抵のプラグインは、日本語表示で使っていたら、アップデートしても日本語表示のままですが、このSite Kitだけは、アップデートすると日本語表示が英語表示に変わってしまうのですよ。一旦削除して入れ直すと新バージョンも日本語表示になります。</p>\n\n\n\n<p class=\"wp-block-paragraph\">この謎仕様、たまに治ってる時もあるんですが、今うちのも英語表示に戻ってます。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"mokkosan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:153:\"https://ja.wordpress.org/support/topic/site-kit-by-google%e3%81%ae%e5%89%8a%e9%99%a4%e6%9c%89%e7%84%a1%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694052\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"返信先: Site Kit by Googleの削除有無について\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:153:\"https://ja.wordpress.org/support/topic/site-kit-by-google%e3%81%ae%e5%89%8a%e9%99%a4%e6%9c%89%e7%84%a1%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694052\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 27 Apr 2026 04:38:22 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:575:\"\n						\n						<p class=\"wp-block-paragraph\">皆さん、色々と助言いただきありがとうございます。<br />翻訳の方法など試してみたと思います。またSiteKitは削除しないで行こうと思います。（自力で連携できるスキルがないので）</p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n\n\n\n<p class=\"wp-block-paragraph\">ありがとうございました。<br /></p>\n\n\n\n<p class=\"wp-block-paragraph\">また何かあれば改めて質問させていただきます。その際はよろしくお願いします。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"an1012\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:153:\"https://ja.wordpress.org/support/topic/site-kit-by-google%e3%81%ae%e5%89%8a%e9%99%a4%e6%9c%89%e7%84%a1%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694051\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"返信先: Site Kit by Googleの削除有無について\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:153:\"https://ja.wordpress.org/support/topic/site-kit-by-google%e3%81%ae%e5%89%8a%e9%99%a4%e6%9c%89%e7%84%a1%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694051\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 27 Apr 2026 04:29:21 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:609:\"\n						\n						<p class=\"wp-block-paragraph\">こんにちは。<br />プラグインを削除した場合、AdSenseやSearch Console・Analyticsなどとの連携は解除されてしまいますので、Googleのサイトにログインしてもプラグインを削除する前のデータしか見れなくなります。</p>\n\n\n\n<p class=\"wp-block-paragraph\">テーマの設定やフック等を使用して、自力で連携できるのであれば削除してもいいと思いますが、それが難しいのならプラグインはそのまま使ったほうがいいと思います。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"まーちゅう\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:153:\"https://ja.wordpress.org/support/topic/site-kit-by-google%e3%81%ae%e5%89%8a%e9%99%a4%e6%9c%89%e7%84%a1%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694050\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"返信先: Site Kit by Googleの削除有無について\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:153:\"https://ja.wordpress.org/support/topic/site-kit-by-google%e3%81%ae%e5%89%8a%e9%99%a4%e6%9c%89%e7%84%a1%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694050\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 27 Apr 2026 04:04:31 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:646:\"\n						\n						<p class=\"wp-block-paragraph\">Site Kitというプラグインは私は使っていないですが、日本語に翻訳されていない箇所があるようですね。</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://translate.wordpress.org/locale/ja/default/wp-plugins/?filter=&amp;without-editors=&amp;s=site-kit\" rel=\"nofollow ugc\">https://translate.wordpress.org/locale/ja/default/wp-plugins/?filter=&#038;without-editors=&#038;s=site-kit</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">↑のページから日本語訳を登録すればメッセージなどが日本語で表示されるかと思います。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"水野史土\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:153:\"https://ja.wordpress.org/support/topic/site-kit-by-google%e3%81%ae%e5%89%8a%e9%99%a4%e6%9c%89%e7%84%a1%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694049\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"返信先: Site Kit by Googleの削除有無について\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:153:\"https://ja.wordpress.org/support/topic/site-kit-by-google%e3%81%ae%e5%89%8a%e9%99%a4%e6%9c%89%e7%84%a1%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694049\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 27 Apr 2026 02:20:15 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1542:\"\n						\n						<p class=\"wp-block-paragraph\">Site Kit by Google のプラグインは、WordPress のダッシュボードで、「Googleアナリティクス」と「サーチコンソール」のデータ分析ができるのがメリットですが、英語表記がストレスにお感じなるのであれば、</p>\n\n\n\n<ul>\n<li>Site Kit by Googleではなく、「Google アナリティクス」と「サーチコンソール」のそれぞれの画面を別タブで開く</li>\n\n\n\n<li>Google Chrome の拡張機能<a href=\"https://chromewebstore.google.com/detail/google-translate/aapbdbdomjkkjkaonfhkkikfgjllcleb?hl=ja\" target=\"_blank\" rel=\"noreferrer noopener nofollow ugc\">「Google 翻訳</a>」をインストールして、ページ単位で日本語表記に翻訳する</li>\n</ul>\n\n\n\n<figure class=\"wp-block-embed is-type-rich is-provider-imgur wp-block-embed-imgur\"><div class=\"wp-block-embed__wrapper\">\n<blockquote class=\"imgur-embed-pub\" lang=\"en\" data-id=\"a/7yOEgmJ\"><a href=\"https://imgur.com/a/7yOEgmJ\" rel=\"nofollow ugc\">View post on imgur.com</a></blockquote><script async src=\"//s.imgur.com/min/embed.js\" charset=\"utf-8\"></script>\n</div><figcaption class=\"wp-element-caption\">Google Chrome の拡張機能「Google 翻訳」を使って、ページ全体を日本語に翻訳できます</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">どちらかの選択肢をよろしいかと思います。<br />あくまで私の意見ですが、他の方からも助言があるかもしれません。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Yukinobu Asakawa\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:44:\"https://ja.wordpress.org/support/forums/feed\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:10:{s:6:\"server\";s:5:\"nginx\";s:4:\"date\";s:29:\"Thu, 30 Apr 2026 05:58:58 GMT\";s:12:\"content-type\";s:34:\"application/rss+xml; charset=UTF-8\";s:4:\"vary\";s:37:\"Accept-Encoding, accept, content-type\";s:6:\"x-olaf\";s:3:\"⛄\";s:12:\"x-robots-tag\";s:15:\"noindex, follow\";s:15:\"x-frame-options\";s:10:\"SAMEORIGIN\";s:16:\"content-encoding\";s:2:\"br\";s:7:\"alt-svc\";s:19:\"h3=\":443\"; ma=86400\";s:4:\"x-nc\";s:9:\"HIT ord 2\";}s:5:\"build\";i:1760643936;s:21:\"cache_expiration_time\";i:1777571938;s:23:\"__cache_expiration_time\";i:1777571938;}','off'),(147,'_site_transient_timeout_feed_mod_6f409681938158427d2ded6eb1b9ea27','1777571938','off'),(148,'_site_transient_feed_mod_6f409681938158427d2ded6eb1b9ea27','1777528738','off'),(149,'_transient_timeout_dash_v2_45827e8e892dd0b85803a110fad8690f','1777571938','off'),(150,'_transient_dash_v2_45827e8e892dd0b85803a110fad8690f','<div class=\"rss-widget\"><ul><li><a class=\'rsswidget\' href=\'https://ja.wordpress.org/2026/04/25/wordpress-7-0-release-party-updated-schedule/\'>WordPress 7.0 リリーススケジュール更新版</a></li><li><a class=\'rsswidget\' href=\'https://ja.wordpress.org/2026/04/08/watch-wc-asia-2026-live/\'>WordCamp Asia 2026をライブ視聴する方法</a></li></ul></div><div class=\"rss-widget\"><ul><li><a class=\'rsswidget\' href=\'https://ja.wordpress.org/support/topic/site-kit-by-google%E3%81%AE%E5%89%8A%E9%99%A4%E6%9C%89%E7%84%A1%E3%81%AB%E3%81%A4%E3%81%84%E3%81%A6/#post-11694059\'>返信先: Site Kit by Googleの削除有無について</a></li><li><a class=\'rsswidget\' href=\'https://ja.wordpress.org/support/topic/contact-form-7%E3%81%A7%E3%81%AE%E3%82%B3%E3%83%B3%E3%82%BF%E3%82%AF%E3%83%88%E3%83%95%E3%82%A9%E3%83%BC%E3%83%A0%E3%81%AE%E5%AE%9A%E7%BE%A9/#post-11694058\'>返信先: Contact Form 7でのコンタクトフォームの定義</a></li><li><a class=\'rsswidget\' href=\'https://ja.wordpress.org/support/topic/contact-form-7%E3%81%A7%E3%81%AE%E3%82%B3%E3%83%B3%E3%82%BF%E3%82%AF%E3%83%88%E3%83%95%E3%82%A9%E3%83%BC%E3%83%A0%E3%81%AE%E5%AE%9A%E7%BE%A9/#post-11694057\'>返信先: Contact Form 7でのコンタクトフォームの定義</a></li></ul></div>','off');
